INSERT INTO `chat_message` VALUES (6001,5001,'USER','Tôi bị đau đầu, nên làm gì?','2026-05-25 14:31:51'),(6002,5001,'BOT','Bạn nên nghỉ ngơi, uống nhiều nước và có thể dùng paracetamol. Nếu đau nhiều hãy đến khám.','2026-05-25 14:31:51'),(6003,5002,'USER','Chi phí khám chuyên khoa tim mạch bao nhiêu?','2026-05-25 14:31:51'),(6004,5002,'BOT','Phí khám từ 150.000đ đến 650.000đ tùy bác sĩ. Bạn có thể đặt lịch qua ứng dụng.','2026-05-25 14:31:51'),(10000,10000,'USER','Chào bác sĩ, tôi muốn hỏi về kết quả xét nghiệm','2026-06-11 21:00:22'),(10001,10000,'BOT','Chào bạn, kết quả xét nghiệm của bạn bình thường. Các chỉ số đều trong ngưỡng cho phép.','2026-06-11 21:00:22'),(10002,10000,'USER','Cảm ơn bác sĩ, tôi có cần kiêng gì không?','2026-06-11 21:00:22'),(10003,10000,'BOT','Bạn nên duy trì chế độ ăn uống lành mạnh, tập thể dục đều đặn và tái khám đúng lịch.','2026-06-11 21:00:22');
