INSERT INTO `service` VALUES (1,'Gói Xét Nghiệm Sinh Hóa Cơ Bản Tại Nhà','LAB_TEST',30,1015000.00,0,'2026-06-10 18:25:35','/images/services/home/home-pkg-c09a907bb4fb4123913d67fd71b13bd1.jpg','Gói xét nghiệm sinh hóa cơ bản giúp đánh giá chức năng gan, thận, đường máu và mỡ máu. Kết quả nhanh, phù hợp kiểm tra sức khỏe định kỳ.',1,2,'2026-06-11 02:21:57.000000',508000.00),(2,'Gói xét nghiệm sức khỏe sinh sản nữ - nâng cao (6 test)','LAB_TEST',30,1338000.00,0,'2026-06-10 18:25:35','/images/services/home/home-pkg-diag005_DV008.jpg','Gói xét nghiệm toàn diện cho sức khỏe sinh sản nữ, bao gồm 6 chỉ số quan trọng, giúp phát hiện sớm các bất thường nội tiết và phụ khoa.',1,3,'2026-06-11 02:21:57.000000',268000.00),(3,'Gói XN Viêm gan - cơ bản (3 test)','LAB_TEST',30,420000.00,0,'2026-06-10 18:25:35','/images/services/home/home-pkg-diag005_DV011.jpg','Xét nghiệm viêm gan cơ bản với 3 chỉ số: HBsAg, Anti-HCV, men gan. Sàng lọc nguy cơ viêm gan B, C và đánh giá chức năng gan.',1,5,'2026-06-11 02:21:57.000000',126000.00),(4,'Gói XN đái tháo đường - cơ bản (3 test)','LAB_TEST',30,159000.00,0,'2026-06-10 18:25:35','/images/services/home/home-pkg-diag005_DV013.jpg','Xét nghiệm đái tháo đường cơ bản với đường máu đói, HbA1c, và dung nạp glucose, giúp phát hiện sớm tiểu đường và tiền đái tháo đường.',1,4,'2026-06-11 02:21:57.000000',32000.00),(5,'Gói xét nghiệm máu cơ bản - Nam/Nữ','LAB_TEST',30,2110000.00,0,'2026-06-10 18:25:35','/images/services/home/home-pkg-pkvietuc_GK007.jpg','Gói xét nghiệm máu tổng quát cho nam/nữ, bao gồm công thức máu, đường máu, mỡ máu, chức năng gan thận – đánh giá sức khỏe tổng thể.',1,1,'2026-06-11 02:21:57.000000',1055000.00),(6,'Gói XN Viêm gan - nâng cao (6 test)','LAB_TEST',30,1117000.00,0,'2026-06-10 18:25:35','/images/services/home/home-pkg-diag005_DV012.jpg','Gói xét nghiệm viêm gan nâng cao với 6 chỉ số: HBsAg, Anti-HBs, Anti-HCV, HBV-DNA, HCV-RNA và men gan. Phát hiện chi tiết tình trạng nhiễm virus.',1,6,'2026-06-11 02:21:57.000000',559000.0